<template><div><div class="page-head"><div><h1>Branches</h1><p>Manage locations and operational units.</p></div><button class="btn btn-primary" @click="openCreate">+ New branch</button></div><div class="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3"><div v-for="b in branches" :key="b.id" class="card card-hover p-5"><div class="flex items-start justify-between"><div><div class="text-lg font-bold">{{b.name}}</div><div class="mt-1 text-[10px] uppercase tracking-wider text-slate-400">{{b.code}}</div></div><StatusBadge :value="b.is_active"/></div><div class="mt-5 grid grid-cols-3 gap-2"><div class="rounded-xl bg-slate-50 p-3"><div class="text-lg font-bold">{{b.users_count||0}}</div><div class="text-[9px] text-slate-400">Users</div></div><div class="rounded-xl bg-slate-50 p-3"><div class="text-lg font-bold">{{b.clients_count||0}}</div><div class="text-[9px] text-slate-400">Clients</div></div><div class="rounded-xl bg-slate-50 p-3"><div class="text-lg font-bold">{{b.sales_count||0}}</div><div class="text-[9px] text-slate-400">Sales</div></div></div><div class="mt-5 flex gap-2"><button class="btn btn-soft flex-1" @click="edit(b)">Edit</button><button class="btn btn-danger" @click="remove(b)">Delete</button></div></div></div><AppModal :open="open" :title="editing?'Edit branch':'New branch'" @close="open=false"><form @submit.prevent="save" class="grid gap-4 md:grid-cols-2"><div><label class="label">Branch name *</label><input v-model="form.name" class="input" required></div><div><label class="label">Code *</label><input v-model="form.code" class="input" required></div><div><label class="label">Phone</label><input v-model="form.phone" class="input"></div><div><label class="label">Address</label><input v-model="form.address" class="input"></div><label class="md:col-span-2 flex items-center gap-2 text-xs font-semibold"><input v-model="form.is_active" type="checkbox"> Active branch</label><div class="md:col-span-2 flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" class="btn btn-soft" @click="open=false">Cancel</button><button class="btn btn-primary">Save branch</button></div></form></AppModal><div v-if="error" class="fixed bottom-5 right-5 rounded-xl bg-rose-600 px-4 py-3 text-xs font-bold text-white shadow-xl">{{error}}</div></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {api,apiError} from '../../services/api';import {useConfirm} from '../../stores/confirm';import {useToast} from '../../stores/toast';import AppModal from '../../components/AppModal.vue';import StatusBadge from '../../components/StatusBadge.vue';const {ask:confirm}=useConfirm();const toast=useToast();const branches=ref<any[]>([]),open=ref(false),editing=ref<any>(null),error=ref('');const blank=()=>({name:'',code:'',phone:'',address:'',is_active:true});const form=ref<any>(blank());async function load(){branches.value=(await api.get('/branches')).data}function openCreate(){editing.value=null;form.value=blank();open.value=true}function edit(b:any){editing.value=b;form.value={...blank(),...b};open.value=true}async function save(){try{if(editing.value)await api.put(`/branches/${editing.value.id}`,form.value);else await api.post('/branches',form.value);open.value=false;await load();toast.success(editing.value?'Branch updated':'Branch created', editing.value?'Changes saved successfully.':'Branch was created successfully.')}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}}async function remove(b:any){if(!(await confirm({title:'Delete branch?',message:`You are about to delete ${b.name}. This action cannot be undone.`,confirmText:'Delete',danger:true})))return;try{await api.delete(`/branches/${b.id}`);await load();toast.success('Branch deleted', `${b.name} was deleted successfully.`)}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}}onMounted(load)</script>
